"""Package the captured main-scene workshop journey without synthesizing artwork."""
from pathlib import Path
import json,hashlib,html
from PIL import Image,ImageDraw
HERE=Path(__file__).resolve().parent;ROOT=HERE.parent.parent
OUT=ROOT/'output/bill-workshop-carry-journey'
data=json.loads((OUT/'journeys.json').read_text());validation=json.loads((OUT/'validation.json').read_text())
assert validation['passed'] and data['failures']==0
sections=[];metrics=[]
for journey in data['journeys']:
 files=journey['captures'];board=Image.new('RGB',(1200,240*((len(files)+3)//4)),'#22343e');draw=ImageDraw.Draw(board)
 for i,name in enumerate(files):
  step=int(name[-7:-4]);record=journey['records'][step];foot=record['foot']
  # This fixed camera's room spans398px/cell; native floor origin is255,287.
  # Approximate crop centers only; originals remain available for contact review.
  x=255+(foot[0]-7680)*398/384;y=287+(foot[1]-7680)*398/384
  native=Image.open(OUT/name).convert('RGB');crop=native.crop((round(x)-75,round(y)-130,round(x)+75,round(y)+50))
  bx=i%4*300;by=i//4*240;board.paste(crop,(bx,by+30))
  source=Image.open(OUT/name.replace(f'-{step:03d}.png',f'-source-{step:03d}.png')).convert('RGBA').resize((142,142),Image.Resampling.LANCZOS)
  board.paste(source,(bx+150,by+55),source)
  draw.text((bx+5,by+5),f'{step/60:.2f}s {record["direction"]} {record["stage"]}',fill='#dde8e9');draw.text((bx+5,by+214),'NATIVE ROOM        SOURCE 82',fill='#dde8e9')
 tag=('staged' if journey['candidate'] else 'normal')+('-helmet' if journey['helmet'] else '-bare');board.save(OUT/(tag+'-review.png'))
 held=[r for r in journey['records'] if r['clip']];ranges=[max(r['foot'][axis] for r in held)-min(r['foot'][axis] for r in held) for axis in [0,1]]
 metrics.append({'comparison':tag,'displayedTurnFootRangeXY':ranges,'turns':journey['turns'],'captures':len(files)})
 links=' '.join(f'<a href="../../output/bill-workshop-carry-journey/{name}">{name[-7:-4]}</a>' for name in files)
 sections.append(f'<h2>{html.escape(tag)}</h2><p>Full station captures: {links}</p><img src="../../output/bill-workshop-carry-journey/{tag}-review.png">')
(HERE/'workshop-review.html').write_text('''<!doctype html><meta charset="utf-8"><title>Bill workshop planted-turn preview</title><style>body{background:#182932;color:#dde8e9;font:16px system-ui;margin:24px}img{max-width:100%}a{color:#aed7df;margin-right:12px}</style><h1>Bill — workshop carry comparison</h1><p>The preview movement holds Bill in place during the turn, then follows his real workshop route. Current movement slides him across the floor while the pivot plays.</p><p>Unselected authoring preview. The first carrying stride still needs a smoother handoff. Checkpoint and interruption support remain unfinished.</p><p>The workshop route exercises the existing East/West half-turn, not the newly authored East/South quarter artwork. Entry into the workshop service is prescribed; the carry path is generated by the production controller.</p><a href="corner-planted-review.html">Moving quarter-turn replay</a>'''+''.join(sections),encoding='utf-8')
inputs=[ROOT/'tests/test_bill_workshop_carry_journey.gd',HERE/'carry_motion_preview.gd',OUT/'journeys.json',OUT/'validation.json']
evidence={'scope':data['scope'],'checks':data['checks'],'validation':validation,'comparisons':metrics,'nativeVisualReview':'All36native room/source views across four boards reviewed; actor visible/matte/station stature coherent. First carry stride and unload-facing snap remain unresolved.','sourceScope':'Actual workshop route uses existing selected East/West half-turn; staged East/South artwork exercised separately in quarter fixture.','normalSelectionChanged':False,'goalComplete':False,'hashTiming':'After native run; dependency stability during interval unmeasured.','inputHashes':{p.relative_to(ROOT).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in inputs}}
(HERE/'workshop-runtime-evidence.json').write_text(json.dumps(evidence,indent=2)+'\n',encoding='utf-8')
print(f"Packaged {sum(len(j['captures']) for j in data['journeys'])} native views; {data['checks']} checks; staged hold ranges: {[m['displayedTurnFootRangeXY'] for m in metrics if m['comparison'].startswith('staged')]}")
